import React, { useState, useEffect } from 'react';
import axios from 'axios';

const API_URL = 'http://localhost:8000/api/translation-units'; // Adjust the URL as needed

function App() {
  const [translationUnits, setTranslationUnits] = useState([]);
  const [newTranslation, setNewTranslation] = useState('');
  const [selectedUnit, setSelectedUnit] = useState(null);

  // Fetch translation units on initial render
  useEffect(() => {
    fetchTranslationUnits();
  }, []);

  // Fetch translation units from the API
  const fetchTranslationUnits = async () => {
    try {
      const response = await axios.get(API_URL);
      setTranslationUnits(response.data.data);
    } catch (error) {
      console.error('Error fetching translation units:', error);
    }
  };

  // Add a new translation unit
  const addTranslationUnit = async () => {
    try {
      await axios.post(API_URL, {
        source_text: newTranslation,
        language_id: 1, // Assuming language ID for English
      });
      setNewTranslation('');
      fetchTranslationUnits();
    } catch (error) {
      console.error('Error adding translation unit:', error);
    }
  };

  // Edit a translation unit
  const updateTranslationUnit = async (id) => {
    try {
      await axios.put(`${API_URL}/${id}`, {
        source_text: newTranslation,
        status: 'in-progress', // Assuming status update
      });
      setNewTranslation('');
      fetchTranslationUnits();
    } catch (error) {
      console.error('Error updating translation unit:', error);
    }
  };

  // Delete a translation unit
  const deleteTranslationUnit = async (id) => {
    try {
      await axios.delete(`${API_URL}/${id}`);
      fetchTranslationUnits();
    } catch (error) {
      console.error('Error deleting translation unit:', error);
    }
  };

  return (
    <div className="App">
      <h1>Translation Units</h1>

      {/* Add Translation Unit Form */}
      <div>
        <input
          type="text"
          value={newTranslation}
          onChange={(e) => setNewTranslation(e.target.value)}
          placeholder="Enter new translation"
        />
        <button onClick={addTranslationUnit}>Add Translation Unit</button>
      </div>

      {/* Translation Units List */}
      <ul>
        {translationUnits.map((unit) => (
          <li key={unit.id}>
            <span>{unit.source_text}</span>
            <button onClick={() => setSelectedUnit(unit.id)}>Edit</button>
            <button onClick={() => deleteTranslationUnit(unit.id)}>Delete</button>
          </li>
        ))}
      </ul>

      {/* Edit Translation */}
      {selectedUnit && (
        <div>
          <h2>Edit Translation Unit</h2>
          <input
            type="text"
            value={newTranslation}
            onChange={(e) => setNewTranslation(e.target.value)}
            placeholder="Update translation"
          />
          <button onClick={() => updateTranslationUnit(selectedUnit)}>Update</button>
        </div>
      )}
    </div>
  );
}

export default App;
